tests.src/test/java/ae/minisql/DifferentialTes:
package ae.minisql;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.TreeMap;
import org.junit.jupiter.api.Test;

/** Randomised NAIVE-vs-OPTIMIZED differential tests plus an independent stream-based oracle. */
class DifferentialTest {

    private static final String[] STR = {"x", "y", "xy", "yx"};

    /** Three tables t0..t2 with columns a INT, b INT, s TEXT, f BOOL, nullable, tiny value domains (so joins hit). */
    private static Database randomDb(Random rnd) {
        Database db = new Database();
        for (int t = 0; t < 3; t++) {
            db.execute("create table t" + t + " (a int, b int, s text, f bool)");
            int n = rnd.nextInt(9); // 0..8 rows, empty tables included
            for (int i = 0; i < n; i++) {
                db.execute("insert into t" + t + " values (" + nullable(rnd, "" + rnd.nextInt(4)) + ", "
                        + nullable(rnd, "" + rnd.nextInt(4)) + ", " + nullable(rnd, "'" + STR[rnd.nextInt(4)] + "'")
                        + ", " + nullable(rnd, rnd.nextBoolean() ? "true" : "false") + ")");
            }
        }
        return db;
    }

    private static String nullable(Random rnd, String v) {
        return rnd.nextInt(6) == 0 ? "null" : v;
    }

    private static String intCol(Random rnd, int rels) {
        return "q" + rnd.nextInt(rels) + "." + (rnd.nextBoolean() ? "a" : "b");
    }

    private static String intExpr(Random rnd, int rels, int depth) {
        int c = depth <= 0 ? rnd.nextInt(2) : rnd.nextInt(5);
        return switch (c) {
            case 0, 1 -> rnd.nextInt(4) == 0 ? "" + rnd.nextInt(4) : intCol(rnd, rels);
            case 2 -> "(" + intExpr(rnd, rels, depth - 1) + " + " + intExpr(rnd, rels, depth - 1) + ")";
            case 3 -> "(" + intExpr(rnd, rels, depth - 1) + " - 1)";
            default -> "(" + intExpr(rnd, rels, depth - 1) + " * 2)";
        };
    }

    private static String boolExpr(Random rnd, int rels, int depth) {
        int c = depth <= 0 ? rnd.nextInt(6) : rnd.nextInt(10);
        String strCol = "q" + rnd.nextInt(rels) + ".s";
        return switch (c) {
            case 0, 1 -> intExpr(rnd, rels, 1) + " " + new String[] {"=", "<>", "<", "<=", ">", ">="}[rnd.nextInt(6)] + " "
                    + intExpr(rnd, rels, 1);
            case 2 -> strCol + " = '" + STR[rnd.nextInt(4)] + "'";
            case 3 -> strCol + (rnd.nextBoolean() ? " like " : " not like ") + "'" + new String[] {"x%", "%y", "_y", "%"}[rnd.nextInt(4)] + "'";
            case 4 -> intCol(rnd, rels) + (rnd.nextBoolean() ? " is null" : " is not null");
            case 5 -> "q" + rnd.nextInt(rels) + ".f";
            case 6 -> "not (" + boolExpr(rnd, rels, depth - 1) + ")";
            case 7 -> "(" + boolExpr(rnd, rels, depth - 1) + " and " + boolExpr(rnd, rels, depth - 1) + ")";
            case 8 -> "(" + boolExpr(rnd, rels, depth - 1) + " or " + boolExpr(rnd, rels, depth - 1) + ")";
            default -> intCol(rnd, rels) + (rnd.nextBoolean() ? " in (" : " not in (") + rnd.nextInt(4) + ", " + nullable(rnd, "" + rnd.nextInt(4)) + ")";
        };
    }

    /** Returns one random SELECT; rows are totally ordered by ORDER BY over every output column. */
    private static String randomQuery(Random rnd) {
        int rels = 1 + rnd.nextInt(3);
        StringBuilder from = new StringBuilder("from t" + rnd.nextInt(3) + " q0");
        for (int i = 1; i < rels; i++) {
            String on = rnd.nextInt(5) == 0
                    ? boolExpr(rnd, i + 1, 1)
                    : "q" + rnd.nextInt(i) + "." + (rnd.nextBoolean() ? "a" : "b") + " = q" + i + "." + (rnd.nextBoolean() ? "a" : "b")
                            + (rnd.nextInt(3) == 0 ? " and " + boolExpr(rnd, i + 1, 1) : "");
            from.append(rnd.nextInt(3) == 0 ? " left join " : " join ").append("t").append(rnd.nextInt(3)).append(" q").append(i).append(" on ").append(on);
        }
        String where = rnd.nextInt(3) == 0 ? "" : " where " + boolExpr(rnd, rels, 2);
        StringBuilder sb = new StringBuilder("select ");
        int items;
        if (rnd.nextInt(3) == 0) { // grouped
            List<String> keys = new ArrayList<>();
            for (int k = 1 + rnd.nextInt(2); k > 0; k--) keys.add(intCol(rnd, rels));
            List<String> sel = new ArrayList<>(keys);
            for (int k = 1 + rnd.nextInt(3); k > 0; k--) {
                sel.add(new String[] {"count(*)", "count(" + intCol(rnd, rels) + ")", "sum(" + intExpr(rnd, rels, 1) + ")",
                        "min(" + intCol(rnd, rels) + ")", "max(q0.s)", "count(distinct " + intCol(rnd, rels) + ")"}[rnd.nextInt(6)]);
            }
            items = sel.size();
            sb.append(String.join(", ", sel)).append(' ').append(from).append(where).append(" group by ").append(String.join(", ", keys));
            if (rnd.nextInt(3) == 0) sb.append(" having count(*) > ").append(rnd.nextInt(3));
        } else {
            List<String> sel = new ArrayList<>();
            for (int k = 1 + rnd.nextInt(4); k > 0; k--) {
                sel.add(rnd.nextInt(3) == 0 ? intExpr(rnd, rels, 2) : rnd.nextBoolean() ? "q" + rnd.nextInt(rels) + ".s" : intCol(rnd, rels));
            }
            items = sel.size();
            if (rnd.nextInt(4) == 0) sb.append("distinct ");
            sb.append(String.join(", ", sel)).append(' ').append(from).append(where);
        }
        sb.append(" order by ");
        for (int i = 1; i <= items; i++) sb.append(i == 1 ? "" : ", ").append(i).append(rnd.nextInt(4) == 0 ? " desc" : "");
        if (rnd.nextInt(4) == 0) sb.append(" limit ").append(rnd.nextInt(6)).append(rnd.nextBoolean() ? " offset 1" : "");
        return sb.toString();
    }

    @Test
    void plannersAgreeOnRandomQueries() {
        int nonEmpty = 0, hashJoins = 0, leftJoins = 0, grouped = 0, queries = 0, pushed = 0;
        for (int seed = 0; seed < 150; seed++) {
            Random rnd = new Random(seed);
            Database db = randomDb(rnd);
            for (int q = 0; q < 12; q++) {
                String sql = randomQuery(rnd);
                db.setPlanner(Planner.NAIVE);
                Result naive = db.execute(sql);
                String naivePlan = String.join("|", db.lastPlan());
                db.setPlanner(Planner.OPTIMIZED);
                Result opt = db.execute(sql);
                String optPlan = String.join("|", db.lastPlan());
                String ctx = "seed=" + seed + " q=" + q + " sql=" + sql;
                assertEquals(naive.columns(), opt.columns(), ctx);
                assertEquals(naive.rows(), opt.rows(), ctx);
                assertFalse(naivePlan.contains("hash-join"), ctx);
                queries++;
                if (!opt.rows().isEmpty()) nonEmpty++;
                if (optPlan.contains("hash-join")) hashJoins++;
                if (sql.contains(" left join ")) leftJoins++;
                if (sql.contains(" group by ")) grouped++;
                if (optPlan.matches(".*scan \\w+ as q\\d filter=[1-9].*")) pushed++;
            }
        }
        // outcome mix: the generator must actually reach the interesting paths
        assertEquals(1800, queries);
        assertTrue(nonEmpty > queries * 0.35, "non-empty results " + nonEmpty);
        assertTrue(hashJoins > 300, "hash joins " + hashJoins);
        assertTrue(leftJoins > 150, "left joins " + leftJoins);
        assertTrue(grouped > 300, "grouped " + grouped);
        assertTrue(pushed > 300, "pushdown " + pushed);
    }

    /** Independent oracle: plain collections, no SQL machinery. Inner equi-join + group + sum + count. */
    @Test
    void joinGroupAggregateMatchesCollectionsOracle() {
        for (int seed = 0; seed < 60; seed++) {
            Random rnd = new Random(1000 + seed);
            Database db = new Database();
            db.execute("create table l (k int, v int)");
            db.execute("create table r (k int, w int)");
            List<Long[]> l = new ArrayList<>(), r = new ArrayList<>();
            for (int i = rnd.nextInt(15); i >= 0; i--) {
                Long[] row = {rnd.nextInt(5) == 0 ? null : (long) rnd.nextInt(4), rnd.nextInt(4) == 0 ? null : (long) rnd.nextInt(10)};
                l.add(row);
                db.execute("insert into l values (" + row[0] + ", " + row[1] + ")");
            }
            for (int i = rnd.nextInt(15); i >= 0; i--) {
                Long[] row = {rnd.nextInt(5) == 0 ? null : (long) rnd.nextInt(4), (long) rnd.nextInt(10)};
                r.add(row);
                db.execute("insert into r values (" + row[0] + ", " + row[1] + ")");
            }
            // oracle: group by l.k over matching pairs -> (count(*), sum(l.v), max(r.w))
            Map<Long, long[]> groups = new TreeMap<>(); // [count, sum, sumNonNull?1:0, max]
            for (Long[] a : l) for (Long[] b : r) {
                if (a[0] == null || b[0] == null || !a[0].equals(b[0])) continue;
                long[] g = groups.computeIfAbsent(a[0], x -> new long[] {0, 0, 0, Long.MIN_VALUE});
                g[0]++;
                if (a[1] != null) { g[1] += a[1]; g[2] = 1; }
                g[3] = Math.max(g[3], b[1]);
            }
            List<List<Object>> want = new ArrayList<>();
            for (Map.Entry<Long, long[]> e : groups.entrySet()) {
                long[] g = e.getValue();
                want.add(Fx.row(e.getKey(), g[0], g[2] == 1 ? (Object) g[1] : null, g[3]));
            }
            for (Planner p : Planner.values()) {
                db.setPlanner(p);
                assertEquals(want, db.execute("select l.k, count(*), sum(l.v), max(r.w) from l join r on l.k = r.k group by l.k order by l.k").rows(),
                        "seed " + seed + " " + p);
            }
        }
    }

    @Test
    void leftJoinOracle() {
        for (int seed = 0; seed < 60; seed++) {
            Random rnd = new Random(5000 + seed);
            Database db = new Database();
            db.execute("create table l (k int, v int)");
            db.execute("create table r (k int, w int)");
            List<Long[]> l = new ArrayList<>(), r = new ArrayList<>();
            for (int i = rnd.nextInt(8); i >= 0; i--) {
                Long[] row = {rnd.nextInt(5) == 0 ? null : (long) rnd.nextInt(4), (long) i};
                l.add(row);
                db.execute("insert into l values (" + row[0] + ", " + row[1] + ")");
            }
            for (int i = rnd.nextInt(8); i >= 0; i--) {
                Long[] row = {rnd.nextInt(5) == 0 ? null : (long) rnd.nextInt(4), (long) (100 + i)};
                r.add(row);
                db.execute("insert into r values (" + row[0] + ", " + row[1] + ")");
            }
            // l LEFT JOIN r ON l.k = r.k AND r.w >= 103, rows (l.v, r.w); NULL-padded when no pair passes
            List<List<Object>> want = new ArrayList<>();
            for (Long[] a : l) {
                boolean any = false;
                for (Long[] b : r) {
                    if (a[0] != null && a[0].equals(b[0]) && b[1] >= 103) { want.add(Fx.row(a[1], b[1])); any = true; }
                }
                if (!any) want.add(Fx.row(a[1], null));
            }
            want.sort((x, y) -> {
                int c = Long.compare((Long) x.get(0), (Long) y.get(0));
                if (c != 0) return c;
                if (x.get(1) == null || y.get(1) == null) return x.get(1) == null ? (y.get(1) == null ? 0 : -1) : 1;
                return Long.compare((Long) x.get(1), (Long) y.get(1));
            });
            for (Planner p : Planner.values()) {
                db.setPlanner(p);
                assertEquals(want, db.execute("select l.v, r.w from l left join r on l.k = r.k and r.w >= 103 order by l.v, r.w").rows(),
                        "seed " + seed + " " + p);
            }
        }
    }

    @Test
    void largeEquiJoinIsFastWithHashJoin() {
        Database db = new Database();
        db.execute("create table big1 (k int, v int)");
        db.execute("create table big2 (k int, w int)");
        StringBuilder a = new StringBuilder("insert into big1 values "), b = new StringBuilder("insert into big2 values ");
        int n = 3000;
        for (int i = 0; i < n; i++) {
            a.append(i == 0 ? "" : ",").append("(").append(i).append(",").append(i % 7).append(")");
            b.append(i == 0 ? "" : ",").append("(").append(n - 1 - i).append(",").append(i % 5).append(")");
        }
        db.execute(a.toString());
        db.execute(b.toString());
        db.setPlanner(Planner.OPTIMIZED);
        long t0 = System.nanoTime();
        Result r = db.execute("select count(*), sum(v + w) from big1 join big2 on big1.k = big2.k");
        long ms = (System.nanoTime() - t0) / 1_000_000;
        assertEquals(1, r.rows().size());
        assertEquals(3000L, r.rows().get(0).get(0));
        assertTrue(ms < 3000, "hash join over " + n + "x" + n + " took " + ms + " ms");
    }
}

tests.src/test/java/ae/minisql/DmlTest.java:
package ae.minisql;

import static ae.minisql.Fx.*;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class DmlTest {
    @Test
    void insertReportsAffectedAndColumnListFillsNulls() {
        Database db = company();
        Result r = db.execute("insert into emp (name, id) values ('fy', 6), ('gi', 7)");
        assertEquals(2, r.affected());
        assertEquals(List.of(row(6L, "fy", null, null, null)), rows(db, "select * from emp where id = 6"));
    }

    @Test
    void updateUsesOldRowValuesForAllAssignments() {
        Database db = company();
        // swap-like semantics: both right-hand sides see the OLD row
        assertEquals(1, db.execute("update emp set salary = boss, boss = salary where id = 2").affected());
        assertEquals(List.of(row(1L, 80L)), rows(db, "select salary, boss from emp where id = 2"));
        assertEquals(5, db.execute("update emp set salary = salary + 1").affected());
        assertEquals(List.of(row((Object) null)), rows(db, "select salary from emp where id = 5")); // NULL + 1 stays NULL
        assertEquals(List.of(row(101L)), rows(db, "select salary from emp where id = 1"));
    }

    @Test
    void updateWithNullPredicateTouchesNothing() {
        Database db = company();
        assertEquals(0, db.execute("update emp set name = 'z' where salary > 1000").affected());
        assertEquals(0, db.execute("update emp set name = 'z' where null").affected());
        assertEquals(List.of(row("ed")), rows(db, "select name from emp where id = 5"));
    }

    @Test
    void failedUpdateLeavesTableUntouched() {
        Database db = company();
        // moving ids by +1 collides with an existing key on the last row processed: nothing may change
        assertThrows(SqlException.class, () -> db.execute("update emp set id = 3 where id < 3"));
        assertEquals(List.of(row(1L), row(2L), row(3L), row(4L), row(5L)), rows(db, "select id from emp order by id"));
        assertThrows(SqlException.class, () -> db.execute("update emp set name = null where id >= 1"));
        assertEquals(List.of(row("ann")), rows(db, "select name from emp where id = 1"));
        // a division by zero on the last matching row must not leave earlier rows updated
        assertThrows(SqlException.class, () -> db.execute("update emp set salary = 100 / (id - 5)"));
        assertEquals(List.of(row(100L)), rows(db, "select salary from emp where id = 1"));
    }

    @Test
    void updatingPrimaryKeyToItselfOrPermutingIsAllowedWhenFinalStateIsUnique() {
        Database db = new Database();
        db.execute("create table k (id int primary key, v int)");
        db.execute("insert into k values (1,10),(2,20),(3,30)");
        db.execute("update k set id = id + 1"); // transient collisions are fine: only the final state counts
        assertEquals(List.of(row(2L), row(3L), row(4L)), rows(db, "select id from k order by id"));
    }

    @Test
    void failedMultiRowInsertIsAtomic() {
        Database db = company();
        assertThrows(SqlException.class, () -> db.execute("insert into dept values (10,'a'),(11,'b'),(10,'c')"));
        assertEquals(3, rows(db, "select id from dept").size());
        assertThrows(SqlException.class, () -> db.execute("insert into dept values (10,'a'),(11,5)"));
        assertEquals(3, rows(db, "select id from dept").size());
    }

    @Test
    void delete() {
        Database db = company();
        assertEquals(2, db.execute("delete from emp where dept = 2").affected());
        assertEquals(0, db.execute("delete from emp where salary > 1000").affected());
        assertEquals(3, rows(db, "select id from emp").size());
        assertEquals(3, db.execute("delete from emp").affected());
        assertEquals(List.of(row(0L)), rows(db, "select count(*) from emp"));
    }

    @Test
    void dropTable() {
        Database db = company();
        db.execute("drop table emp");
        assertThrows(SqlException.class, () -> db.execute("select * from emp"));
        db.execute("create table emp (x int)"); // name is reusable
        assertEquals(List.of(), rows(db, "select x from emp"));
    }

    @Test
    void rollbackRestoresDataAndDdl() {
        Database db = company();
        db.execute("begin");
        db.execute("delete from emp");
        db.execute("insert into dept values (9,'new')");
        db.execute("create table tmp (a int)");
        db.execute("drop table dept");
        db.execute("rollback");
        assertEquals(5, rows(db, "select id from emp").size());
        assertEquals(3, rows(db, "select id from dept").size());
        assertThrows(SqlException.class, () -> db.execute("select a from tmp"));
    }

    @Test
    void commitKeepsChangesAndRollbackAfterCommitIsRejected() {
        Database db = company();
        db.execute("begin");
        db.execute("delete from emp where id = 1");
        db.execute("commit");
        assertThrows(SqlException.class, () -> db.execute("rollback"));
        assertEquals(4, rows(db, "select id from emp").size());
    }

    @Test
    void snapshotIsDeepSoUpdatesAfterBeginAreUndone() {
        Database db = company();
        db.execute("begin");
        db.execute("update emp set name = 'changed'");
        db.execute("rollback");
        assertEquals(List.of(row("ann")), rows(db, "select name from emp where id = 1"));
        // and rows handed out earlier are not aliased with live storage
        List<List<Object>> before = rows(db, "select name from emp where id = 1");
        db.execute("update emp set name = 'zzz' where id = 1");
        assertEquals(List.of(row("ann")), before);
    }

    @Test
    void scriptRunsStatementsInOrder() {
        Database db = new Database();
        Result last = db.executeScript("create table s (a int); insert into s values (1),(2); select sum(a) from s;");
        assertEquals(List.of(row(3L)), last.rows());
        assertThrows(SqlException.class, () -> db.executeScript("select 1 from s; select zz from s"));
    }
}

tests.src/test/java/ae/minisql/ErrorsTest.java:
package ae.minisql;

import static ae.minisql.Fx.*;
import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class ErrorsTest {
    private static String err(Database db, String sql) {
        SqlException e = assertThrows(SqlException.class, () -> db.execute(sql), sql);
        return e.getMessage();
    }

    @Test
    void parseErrorsCarryLineAndColumn() {
        Database db = company();
        String sql = "select id\nfrom emp\nwhere id = = 3";
        int col = sql.split("\n")[2].indexOf("= 3") + 1; // second '=' on line 3
        String m = err(db, sql);
        assertTrue(m.contains("line 3, col " + col), m);
    }

    @Test
    void eachMalformedStatementIsRejectedWithItsOwnMessage() {
        Database db = company();
        assertTrue(err(db, "select from emp").contains("expression"), "missing item");
        assertTrue(err(db, "select id emp").contains("FROM"), "missing FROM");
        assertTrue(err(db, "select id from emp where").contains("expression"), "dangling where");
        assertTrue(err(db, "select id from emp limit x").contains("number"), "bad limit");
        assertTrue(err(db, "select 'abc from emp").contains("unterminated"), "unterminated string");
        assertTrue(err(db, "select id from emp #").contains("unexpected character"), "stray char");
        assertTrue(err(db, "select id from emp where id in ()").contains("expression"), "empty IN");
        assertTrue(err(db, "create table z (a blob)").contains("type"), "unknown type");
        assertTrue(err(db, "create table z (a int primary key, b int primary key)").contains("PRIMARY KEY"), "two pks");
        assertTrue(err(db, "select id from emp; select 1").contains("end of statement"), "two stmts via execute");
        assertTrue(err(db, "frobnicate").contains("statement"), "unknown statement");
        assertTrue(err(db, "select id from emp where id = 99999999999999999999").contains("range"), "huge literal");
    }

    @Test
    void staticNameErrors() {
        Database db = company();
        assertTrue(err(db, "select nope from emp").contains("unknown column"));
        assertTrue(err(db, "select x.id from emp").contains("unknown column"));
        assertTrue(err(db, "select id from emp e join dept d on e.dept = d.id").contains("ambiguous"));
        assertTrue(err(db, "select id from nosuch").contains("unknown table"));
        assertTrue(err(db, "select * from emp e join emp e on 1 = 1").contains("duplicate"));
    }

    @Test
    void staticErrorsFireEvenOnEmptyTables() {
        Database db = new Database();
        db.execute("create table a (x int)");
        db.execute("create table b (x int)");
        for (Planner p : Planner.values()) {
            db.setPlanner(p);
            assertTrue(err(db, "select x from a join b on a.x = b.x").contains("ambiguous"), p.name());
            assertTrue(err(db, "select a.x from a where zz = 1").contains("unknown column"), p.name());
        }
    }

    @Test
    void groupingErrors() {
        Database db = company();
        assertTrue(err(db, "select name, count(*) from emp group by dept").contains("GROUP BY"));
        assertTrue(err(db, "select name, count(*) from emp").contains("GROUP BY"));
        assertTrue(err(db, "select count(sum(id)) from emp").contains("nested"));
        assertTrue(err(db, "select id from emp where count(*) > 1").contains("aggregate"));
        assertTrue(err(db, "select id from emp e join dept d on count(*) = 1").contains("aggregate"));
        assertTrue(err(db, "select id from emp having id > 1").contains("GROUP BY"));
        assertTrue(err(db, "select sum(name) from emp").contains("SUM"));
        assertTrue(err(db, "select dept, count(*) from emp group by dept order by name").contains("GROUP BY"));
        // an expression made from group keys is fine
        assertEquals(2, rows(db, "select dept + 1, count(*) from emp where dept is not null group by dept").size());
    }

    @Test
    void ddlAndConstraintErrors() {
        Database db = company();
        assertTrue(err(db, "create table emp (a int)").contains("already exists"));
        assertTrue(err(db, "drop table nosuch").contains("unknown table"));
        assertTrue(err(db, "insert into emp values (1,'dup',1,1,1)").contains("duplicate key"));
        assertTrue(err(db, "insert into emp (id) values (9)").contains("NOT NULL"));
        assertTrue(err(db, "insert into emp values (9,'x')").contains("expects"));
        assertTrue(err(db, "insert into emp (id,id,name) values (9,9,'x')").contains("duplicate column"));
        assertTrue(err(db, "insert into emp values (9,5,1,1,1)").contains("type"));
        assertTrue(err(db, "insert into emp values (9,'n',id,1,1)").contains("column"));
        assertTrue(err(db, "insert into emp values (null,'n',1,1,1)").contains("NOT NULL"));
        assertTrue(err(db, "update emp set nope = 1").contains("unknown column"));
        assertTrue(err(db, "update emp set salary = 'x'").contains("type"));
    }

    @Test
    void transactionErrors() {
        Database db = company();
        assertTrue(err(db, "commit").contains("no transaction"));
        assertTrue(err(db, "rollback").contains("no transaction"));
        db.execute("begin");
        assertTrue(err(db, "begin").contains("already"));
    }
}

tests.src/test/java/ae/minisql/Fx.java:
package ae.minisql;

import java.util.Arrays;
import java.util.List;

/** Shared test helpers. */
final class Fx {
    private Fx() {}

    static List<Object> row(Object... v) {
        return Arrays.asList(v);
    }

    static List<List<Object>> rows(Database db, String sql) {
        return db.execute(sql).rows();
    }

    /** Company fixture. dept: 1 eng, 2 ops, 3 empty. emp: ids 1..5, emp 5 has NULL dept and NULL salary. */
    static Database company() {
        Database db = new Database();
        db.execute("CREATE TABLE dept (id INT PRIMARY KEY, name TEXT NOT NULL)");
        db.execute("INSERT INTO dept VALUES (1,'eng'),(2,'ops'),(3,'empty')");
        db.execute("CREATE TABLE emp (id INT PRIMARY KEY, name TEXT NOT NULL, dept INT, salary INT, boss INT)");
        db.execute("INSERT INTO emp VALUES (1,'ann',1,100,NULL),(2,'bob',1,80,1),(3,'cy',2,70,1),"
                + "(4,'di',2,70,3),(5,'ed',NULL,NULL,3)");
        return db;
    }

    static void bothPlanners(Database db, java.util.function.Consumer<Database> check) {
        for (Planner p : Planner.values()) {
            db.setPlanner(p);
            check.accept(db);
        }
    }
}

tests.src/test/java/ae/minisql/LikeTest.java:
package ae.minisql;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import java.util.regex.Pattern;
import org.junit.jupiter.api.Test;

class LikeTest {
    @Test
    void literalCases() {
        assertTrue(LikeMatcher.matches("", ""));
        assertTrue(LikeMatcher.matches("", "%"));
        assertFalse(LikeMatcher.matches("", "_"));
        assertTrue(LikeMatcher.matches("abc", "a_c"));
        assertTrue(LikeMatcher.matches("abc", "%b%"));
        assertFalse(LikeMatcher.matches("abc", "%d%"));
        assertTrue(LikeMatcher.matches("aXbXc", "a%b%c"));
        assertFalse(LikeMatcher.matches("ab", "a%b%c"));
        assertTrue(LikeMatcher.matches("a.c", "a.c"));
        assertFalse(LikeMatcher.matches("abc", "a.c")); // '.' is literal, not a regex dot
        assertTrue(LikeMatcher.matches("a(b", "a(b"));  // regex metacharacters are literals
        assertFalse(LikeMatcher.matches("ABC", "abc")); // case sensitive
    }

    @Test
    void agreesWithRegexOracleOnRandomInputs() {
        Random rnd = new Random(7);
        String alpha = "ab.(";
        int matches = 0;
        for (int i = 0; i < 20000; i++) {
            StringBuilder t = new StringBuilder();
            for (int n = rnd.nextInt(6); n > 0; n--) t.append(alpha.charAt(rnd.nextInt(alpha.length())));
            StringBuilder p = new StringBuilder();
            StringBuilder re = new StringBuilder();
            for (int n = rnd.nextInt(6); n > 0; n--) {
                int c = rnd.nextInt(6);
                if (c == 0) { p.append('%'); re.append(".*"); }
                else if (c == 1) { p.append('_'); re.append('.'); }
                else { char ch = alpha.charAt(rnd.nextInt(alpha.length())); p.append(ch); re.append(Pattern.quote(String.valueOf(ch))); }
            }
            boolean want = Pattern.compile(re.toString(), Pattern.DOTALL).matcher(t).matches();
            if (want) matches++;
            assertEquals(want, LikeMatcher.matches(t.toString(), p.toString()), "text=" + t + " pattern=" + p);
        }
        assertTrue(matches > 2000 && matches < 18000, "outcome mix " + matches);
    }

    @Test
    void manyPercentsDoNotBlowUp() {
        String text = "a".repeat(200) + "b";
        String pattern = "%a".repeat(30) + "%c";
        long t0 = System.nanoTime();
        assertFalse(LikeMatcher.matches(text, pattern));
        assertTrue((System.nanoTime() - t0) / 1_000_000 < 2000, "pattern matching must be polynomial");
    }
}

tests.src/test/java/ae/minisql/PlanTest.java:
package ae.minisql;

import static ae.minisql.Fx.*;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class PlanTest {
    private static String plan(Database db, Planner p, String sql) {
        db.setPlanner(p);
        db.execute(sql);
        return String.join("\n", db.lastPlan());
    }

    @Test
    void optimizedUsesHashJoinOnEquiConditionAndNaiveDoesNot() {
        Database db = company();
        String sql = "select e.name from emp e join dept d on e.dept = d.id";
        assertTrue(plan(db, Planner.OPTIMIZED, sql).contains("hash-join"));
        assertFalse(plan(db, Planner.NAIVE, sql).contains("hash-join"));
        assertTrue(plan(db, Planner.NAIVE, sql).contains("nested-loop"));
    }

    @Test
    void nonEquiJoinFallsBackToNestedLoop() {
        Database db = company();
        String p = plan(db, Planner.OPTIMIZED, "select e.name from emp e join dept d on e.dept < d.id");
        assertFalse(p.contains("hash-join"), p);
        assertTrue(p.contains("nested-loop"), p);
    }

    @Test
    void equalityWithinOneSideIsNotAJoinKey() {
        Database db = company();
        String p = plan(db, Planner.OPTIMIZED, "select e.name from emp e join dept d on e.dept = e.boss");
        assertFalse(p.contains("hash-join"), p);
    }

    @Test
    void residualPredicateKeptNextToHashKey() {
        Database db = company();
        String sql = "select e.name from emp e join dept d on e.dept = d.id and e.salary > 75 order by e.id";
        assertTrue(plan(db, Planner.OPTIMIZED, sql).contains("hash-join keys=1 residual=1"));
        bothPlanners(db, d -> assertEquals(List.of(row("ann"), row("bob")), rows(d, sql)));
    }

    @Test
    void whereConjunctsArePushedToTheirScanOnlyWhenSafe() {
        Database db = company();
        String p = plan(db, Planner.OPTIMIZED,
                "select e.name from emp e join dept d on e.dept = d.id where e.salary > 75 and d.name = 'eng' and e.id < d.id + 5");
        assertTrue(p.contains("scan emp as e filter=1"), p);
        assertTrue(p.contains("scan dept as d filter=1"), p);
        assertTrue(p.contains("final-filter=1"), p); // the two-table conjunct
        // right side of a LEFT JOIN: the WHERE predicate must NOT be pushed into the scan
        String lp = plan(db, Planner.OPTIMIZED,
                "select d.name from dept d left join emp e on e.dept = d.id where e.id is null");
        assertTrue(lp.contains("scan emp as e filter=0"), lp);
        assertTrue(lp.contains("final-filter=1"), lp);
        // ...but a base-table predicate may be
        String bp = plan(db, Planner.OPTIMIZED,
                "select d.name from dept d left join emp e on e.dept = d.id where d.id > 1");
        assertTrue(bp.contains("scan dept as d filter=1"), bp);
    }

    @Test
    void hashJoinNeverMatchesNullKeys() {
        Database db = new Database();
        db.execute("create table l (k int, v text)");
        db.execute("create table r (k int, w text)");
        db.execute("insert into l values (1,'a'),(null,'b')");
        db.execute("insert into r values (1,'x'),(null,'y')");
        bothPlanners(db, d -> {
            assertEquals(List.of(row("a", "x")), rows(d, "select v, w from l join r on l.k = r.k"));
            assertEquals(List.of(row("a", "x"), row("b", null)),
                    rows(d, "select v, w from l left join r on l.k = r.k order by v"));
        });
    }

    @Test
    void hashJoinHandlesDuplicateKeysAsAProduct() {
        Database db = new Database();
        db.execute("create table l (k int, v int)");
        db.execute("create table r (k int, w int)");
        db.execute("insert into l values (1,1),(1,2),(2,3)");
        db.execute("insert into r values (1,10),(1,20),(3,30)");
        bothPlanners(db, d -> assertEquals(
                List.of(row(1L, 10L), row(1L, 20L), row(2L, 10L), row(2L, 20L)),
                rows(d, "select v, w from l join r on l.k = r.k order by v, w")));
    }

    @Test
    void hashJoinTypeMismatchIsStillAnError() {
        Database db = company();
        for (Planner p : Planner.values()) {
            db.setPlanner(p);
            assertThrows(SqlException.class, () -> db.execute("select 1 from emp e join dept d on e.name = d.id"), p.name());
        }
    }

    @Test
    void joinKeyMayBeAnExpressionOverOneSide() {
        Database db = company();
        String sql = "select e.name, d.name from emp e join dept d on e.dept + 1 = d.id + 0 order by e.id";
        assertTrue(plan(db, Planner.OPTIMIZED, sql).contains("hash-join"));
        bothPlanners(db, d -> assertEquals(List.of(row("ann", "ops"), row("bob", "ops"), row("cy", "empty"), row("di", "empty")), rows(d, sql)));
    }
}

tests.src/test/java/ae/minisql/QueryTest.java:
package ae.minisql;

import static ae.minisql.Fx.*;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class QueryTest {

    @Test
    void projectionFilterOrder() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row("bob", 80L), row("ann", 100L)),
                    rows(db, "select name, salary from emp where salary > 70 order by salary"));
            assertEquals(List.of("name", "pay"),
                    db.execute("SELECT name, salary AS pay FROM emp").columns());
        });
    }

    @Test
    void nullComparisonsAreNotTrue() {
        bothPlanners(company(), db -> {
            // ed has NULL salary: neither '>' nor 'NOT >' keeps it (row 4)
            assertEquals(4, rows(db, "select id from emp where salary > 0").size());
            assertEquals(0, rows(db, "select id from emp where salary > 0 and not (salary > 0) ").size());
            assertEquals(List.of(row(5L)), rows(db, "select id from emp where salary is null"));
            assertEquals(4, rows(db, "select id from emp where salary is not null").size());
            assertEquals(List.of(row(5L)), rows(db, "select id from emp where salary = null or dept is null"));
        });
    }

    @Test
    void threeValuedLogicTable() {
        Database db = company();
        // columns: salary NULL for ed. FALSE AND NULL = FALSE, TRUE OR NULL = TRUE, TRUE AND NULL = NULL
        assertEquals(List.of(row(5L)), rows(db, "select id from emp where (salary is null) and (salary > 1 or true)"));
        assertEquals(List.of(row(false)), rows(db, "select (1 = 2 and salary > 1) from emp where id = 5"));
        assertEquals(List.of(row((Object) null)), rows(db, "select (1 = 1 and salary > 1) from emp where id = 5"));
        assertEquals(List.of(row(true)), rows(db, "select (1 = 1 or salary > 1) from emp where id = 5"));
        assertEquals(List.of(row((Object) null)), rows(db, "select not (salary > 1) from emp where id = 5"));
    }

    @Test
    void arithmeticAndConcat() {
        Database db = company();
        assertEquals(List.of(row(14L, 2L, -7L, "ann!")),
                rows(db, "select 2 + 3 * 4, 17 % 5, -7, name || '!' from emp where id = 1"));
        assertEquals(List.of(row((Object) null)), rows(db, "select salary + 1 from emp where id = 5"));
        assertEquals(List.of(row(Long.MIN_VALUE)), rows(db, "select -9223372036854775808 from emp where id = 1"));
    }

    @Test
    void integerOverflowIsAnError() {
        Database db = company();
        SqlException e = assertThrows(SqlException.class,
                () -> db.execute("select 9223372036854775807 + 1 from emp"));
        assertTrue(e.getMessage().contains("overflow"), e.getMessage());
        assertThrows(SqlException.class, () -> db.execute("select 1 / 0 from emp"));
        assertThrows(SqlException.class, () -> db.execute("select 1 % 0 from emp"));
    }

    @Test
    void inAndNotInWithNulls() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row(1L), row(2L)), rows(db, "select id from emp where dept in (1) order by id"));
            // NOT IN with a NULL in the list never yields TRUE (3VL)
            assertEquals(0, rows(db, "select id from emp where id not in (1, null)").size());
            assertEquals(List.of(row(3L), row(4L)), rows(db, "select id from emp where dept not in (1, 9) order by id"));
        });
    }

    @Test
    void like() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row("ann")), rows(db, "select name from emp where name like 'a%'"));
            assertEquals(List.of(row("bob"), row("cy")), rows(db, "select name from emp where name like '_o_' or name like 'c_' order by name"));
            assertEquals(List.of(row("ann"), row("cy"), row("di"), row("ed")),
                    rows(db, "select name from emp where name not like '%o%' order by name"));
        });
    }

    @Test
    void innerJoinAndAliases() {
        bothPlanners(company(), db -> assertEquals(
                List.of(row("ann", "eng"), row("bob", "eng"), row("cy", "ops"), row("di", "ops")),
                rows(db, "select e.name, d.name from emp e join dept d on e.dept = d.id order by e.id")));
    }

    @Test
    void leftJoinKeepsUnmatchedWithNulls() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row("eng", 2L), row("ops", 2L), row("empty", 0L)),
                    rows(db, "select d.name, count(e.id) from dept d left join emp e on e.dept = d.id "
                            + "group by d.name, d.id order by count(e.id) desc, d.id"));
            assertEquals(List.of(row("empty")),
                    rows(db, "select d.name from dept d left join emp e on e.dept = d.id where e.id is null"));
            // a LEFT JOIN ON predicate on the right side must not drop left rows
            assertEquals(3, rows(db, "select d.id from dept d left join emp e on e.dept = d.id and e.salary > 1000 order by d.id").size());
        });
    }

    @Test
    void selfJoinAndMultiJoin() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row("bob", "ann"), row("cy", "ann"), row("di", "cy"), row("ed", "cy")),
                    rows(db, "select e.name, b.name from emp e join emp b on e.boss = b.id order by e.id"));
            assertEquals(List.of(row("di", "cy", "ops")),
                    rows(db, "select e.name, b.name, d.name from emp e join emp b on e.boss = b.id "
                            + "join dept d on b.dept = d.id where e.id = 4"));
        });
    }

    @Test
    void starExpansion() {
        bothPlanners(company(), db -> {
            Result r = db.execute("select * from dept d join emp e on d.id = e.dept where e.id = 1");
            assertEquals(List.of("id", "name", "id", "name", "dept", "salary", "boss"), r.columns());
            assertEquals(List.of(row(1L, "eng", 1L, "ann", 1L, 100L, null)), r.rows());
            assertEquals(List.of("id", "name"), db.execute("select d.* from dept d").columns());
        });
    }

    @Test
    void groupByAggregates() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row((Object) null, 1L, null), row(1L, 2L, 180L), row(2L, 2L, 140L)),
                    rows(db, "select dept, count(*), sum(salary) from emp group by dept order by dept"));
            assertEquals(List.of(row(1L, 100L, 80L)),
                    rows(db, "select dept, max(salary), min(salary) from emp group by dept having sum(salary) > 150"));
            assertEquals(List.of(row(5L, 4L, 3L, 320L)),
                    rows(db, "select count(*), count(salary), count(distinct salary), sum(salary) from emp"));
            assertEquals(List.of(row("ann"), row("cy")),
                    rows(db, "select min(name) from emp where dept is not null group by dept order by 1"));
        });
    }

    @Test
    void aggregateOverNoRowsGivesOneGroup() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row(0L, null, null)), rows(db, "select count(*), sum(salary), max(name) from emp where id > 99"));
            assertEquals(List.of(), rows(db, "select dept, count(*) from emp where id > 99 group by dept"));
        });
    }

    @Test
    void groupByExpressionAndExpressionOverGroup() {
        bothPlanners(company(), db -> assertEquals(
                List.of(row(0L, 2L), row(1L, 3L)),
                rows(db, "select id % 2, count(*) from emp group by id % 2 order by id % 2")));
        bothPlanners(company(), db -> assertEquals(
                List.of(row(181L)),
                rows(db, "select sum(salary) + 1 from emp where dept = 1")));
    }

    @Test
    void distinctOrderLimitOffset() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row(70L), row(80L), row(100L)),
                    rows(db, "select distinct salary from emp where salary is not null order by salary"));
            assertEquals(List.of(row((Object) null), row(70L), row(80L), row(100L)),
                    rows(db, "select distinct salary from emp order by salary asc"));
            assertEquals(List.of(row(100L), row(80L), row(70L), row((Object) null)),
                    rows(db, "select distinct salary from emp order by salary desc"));
            assertEquals(List.of(row(2L), row(3L)), rows(db, "select id from emp order by id limit 2 offset 1"));
            assertEquals(List.of(), rows(db, "select id from emp limit 0"));
        });
    }

    @Test
    void orderByIsStableAndSupportsAliasOrdinalAndMultipleKeys() {
        bothPlanners(company(), db -> {
            assertEquals(List.of(row("cy"), row("di")),
                    rows(db, "select name from emp where salary = 70 order by salary"));
            assertEquals(List.of(row("ann", 100L), row("bob", 80L), row("cy", 70L), row("di", 70L), row("ed", null)),
                    rows(db, "select name, salary as s from emp order by s desc, 1"));
        });
    }

    @Test
    void caseInsensitiveNamesAndKeywords() {
        Database db = company();
        assertEquals(List.of(row("ann")), rows(db, "SeLeCt NAME fRoM EMP wHeRe ID = 1;"));
        assertEquals(List.of(row(1L)), rows(db, "select E.Id from Emp E where e.NAME = 'ann'"));
    }

    @Test
    void stringLiteralEscape() {
        Database db = new Database();
        db.execute("create table q (s text)");
        db.execute("insert into q values ('it''s')");
        assertEquals(List.of(row("it's")), rows(db, "select s from q"));
    }

    @Test
    void booleanColumnsAndComparisons() {
        Database db = new Database();
        db.execute("create table f (id int, ok bool)");
        db.execute("insert into f values (1, true), (2, false), (3, null)");
        assertEquals(List.of(row(1L)), rows(db, "select id from f where ok"));
        assertEquals(List.of(row(2L)), rows(db, "select id from f where not ok"));
        assertEquals(List.of(row(2L), row(1L)), rows(db, "select id from f where ok is not null order by ok, id"));
        assertEquals(List.of(row(1L), row(2L)), rows(db, "select id from f where ok is not null order by ok desc, id"));
    }

    @Test
    void typeMismatchIsAnError() {
        Database db = company();
        SqlException e = assertThrows(SqlException.class, () -> db.execute("select id from emp where name = 1"));
        assertTrue(e.getMessage().contains("type"), e.getMessage());
        assertThrows(SqlException.class, () -> db.execute("select name + 1 from emp"));
        assertThrows(SqlException.class, () -> db.execute("select id from emp where id"));
    }
}
